//! Materials: MATERIALS (the Materials Browser; its JSON form lists the drawing's materials and the
//! library), material.new / material.edit / material.delete, MATERIALATTACH (a layer's material),
//! MATERIALASSIGN (objects' material; CMATERIAL for new objects) and MATERIALMAP (how textures map
//! onto objects). The model is [`cadaddy_doc::material`]; the library is CADaddy's own
//! (`assets/materials/library.json`), its textures generated by `cadaddy-render`.

use cadaddy_doc::Handle;
use cadaddy_doc::material::{self, Mapping, Material, Projection, Texture};
use serde_json::{Value, json};

use super::machines::{SelOutcome, SelectPhase};
use super::*;
use crate::{Accept, Input, Interactive, Prompt, Result, Session, Step};

pub fn specs() -> Vec<CommandSpec> {
    vec![
        CommandSpec::new("materials", "Materials Browser...", run_list)
            .menu(&["View", "Render", "Materials Browser..."])
            .alias(&["mat", "rmat", "material.list"])
            .params("{} → {materials: [the drawing's], library: [{id, name, category}], current: CMATERIAL} (typed or from the menu: the Materials Browser)")
            .noundo(),
        CommandSpec::new("material.new", "New Material", run_new).params(
            "{library?: id (a library material, sized for the drawing's units), name? (default: the library material's), description?, color?: \"#rrggbb\", roughness?, metallic?, opacity?, refraction?, colorMap?: path, roughnessMap?: path, normalMap?: path, normalStrength?, mapping?: {projection?, sizeU?, sizeV?, offsetU?, offsetV?, rotation?}} → {name}",
        ),
        CommandSpec::new("material.edit", "Edit Material", run_edit).params("{name, rename?, …the fields of material.new (a map \"\" removes it)} → {name}"),
        CommandSpec::new("material.delete", "Delete Material", run_delete).params("{name} → {name, layers, objects} (layers and objects that used it go back to Global / ByLayer)"),
        CommandSpec::new("materialattach", "Attach by Layer", run_attach)
            .menu(&["View", "Render", "Attach by Layer"])
            .params("{layer, material: name | \"Global\" | null (detach)} | {attach: [{layer, material}]} → {changed} (typed: the Materials Browser's layers)")
            .interactive(|_| Ok(Box::new(AttachM::default()))),
        CommandSpec::new("materialassign", "Assign Material", run_assign)
            .params("{handles?: [hex] (default: the selection), material: name | \"ByLayer\" | \"ByBlock\"} → {changed}")
            .interactive(|_| Ok(Box::new(AssignM::default()))),
        CommandSpec::new("materialmap", "Material Mapping", run_map)
            .menu(&["View", "Render", "Material Mapping"])
            .params("{handles?, projection: planar|box|cylindrical|spherical, sizeU?, sizeV?, offsetU?, offsetV?, rotation? (radians)} | {handles?, reset: true} → {changed} (typed: option, then objects)")
            .interactive(|_| Ok(Box::new(MapM::default()))),
    ]
}

fn list_json(m: &Material) -> Value {
    serde_json::to_value(m).unwrap_or(Value::Null)
}

fn run_list(s: &mut Session, _p: &Value) -> Result<Value> {
    let d = s.doc()?;
    let library: Vec<Value> = material::library().iter().map(|r| json!({ "id": r.id, "name": r.name, "category": r.category })).collect();
    Ok(json!({
        "materials": d.materials.iter().map(list_json).collect::<Vec<_>>(),
        "library": library,
        "current": d.header.str("CMATERIAL", material::BY_LAYER),
    }))
}

fn f(p: &Value, key: &str) -> Result<Option<f64>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(v) => v.as_f64().filter(|x| x.is_finite()).map(Some).ok_or_else(|| bad("material", format!("`{key}` must be a number"))),
    }
}

fn text(p: &Value, key: &str) -> Result<Option<String>> {
    match p.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(t)) => Ok(Some(t.chars().take(material::MAX_TEXT).collect())),
        Some(v) => Err(bad("material", format!("`{key}` must be text, got {v}"))),
    }
}

/// Metres per drawing unit of the current drawing.
fn unit_m(s: &Session) -> f64 {
    s.doc().map_or(1.0, |d| material::metres_per_unit(d.header.i64("INSUNITS", 0), d.header.i64("MEASUREMENT", 0) == 1))
}

/// Apply the material fields of `p` to `m`.
fn apply(m: &mut Material, p: &Value) -> Result<()> {
    if let Some(t) = text(p, "description")? {
        m.description = t;
    }
    if let Some(c) = text(p, "color")? {
        m.color = material::parse_hex(&c).ok_or_else(|| bad("material", "`color` must be \"#rrggbb\""))?;
    }
    for (key, field) in [
        ("roughness", &mut m.roughness),
        ("metallic", &mut m.metallic),
        ("opacity", &mut m.opacity),
        ("refraction", &mut m.refraction),
        ("normalStrength", &mut m.normal_strength),
    ] {
        if let Some(v) = f(p, key)? {
            *field = v;
        }
    }
    for (key, field) in [("colorMap", &mut m.color_map), ("roughnessMap", &mut m.roughness_map), ("normalMap", &mut m.normal_map)] {
        if let Some(path) = text(p, key)? {
            *field = (!path.trim().is_empty()).then(|| Texture::File(path.trim().to_string()));
        }
    }
    if let Some(mp) = p.get("mapping").filter(|v| !v.is_null()) {
        m.mapping = mapping(mp, m.mapping)?;
    }
    Ok(())
}

/// A mapping from JSON fields over `base`.
fn mapping(p: &Value, base: Mapping) -> Result<Mapping> {
    let mut out = base;
    if let Some(t) = text(p, "projection")? {
        out.projection =
            Projection::parse(&t).ok_or_else(|| bad("materialmap", format!("unknown projection `{t}` (planar, box, cylindrical or spherical)")))?;
    }
    for (key, field) in [
        ("sizeU", &mut out.size_u),
        ("sizeV", &mut out.size_v),
        ("offsetU", &mut out.offset_u),
        ("offsetV", &mut out.offset_v),
        ("rotation", &mut out.rotation),
    ] {
        if let Some(v) = f(p, key)? {
            *field = v;
        }
    }
    if out.size_u <= 0.0 || out.size_v <= 0.0 {
        return Err(bad("materialmap", "`sizeU` and `sizeV` must be greater than 0"));
    }
    Ok(out.sane())
}

fn check_name(s: &Session, name: &str, except: Option<&str>) -> Result<()> {
    if name.trim().is_empty() {
        return Err(bad("material", "a material needs a name"));
    }
    if Material::is_builtin(name) {
        return Err(bad("material", format!("\"{name}\" is a built-in material name")));
    }
    let d = s.doc()?;
    if d.material(name).is_some() && !except.is_some_and(|e| e.eq_ignore_ascii_case(name.trim())) {
        return Err(bad("material", format!("the drawing already has a material named \"{}\"", name.trim())));
    }
    if d.materials.len() >= material::MAX_MATERIALS && except.is_none() {
        return Err(bad("material", "the drawing has as many materials as it can hold"));
    }
    Ok(())
}

fn run_new(s: &mut Session, p: &Value) -> Result<Value> {
    let mut m = match text(p, "library")? {
        Some(id) => material::recipe(&id).ok_or_else(|| bad("material.new", format!("no library material `{id}`")))?.material(unit_m(s)),
        None => Material::default(),
    };
    if let Some(n) = text(p, "name")? {
        m.name = n.trim().to_string();
    }
    check_name(s, &m.name, None)?;
    apply(&mut m, p)?;
    let m = m.sane();
    let name = m.name.clone();
    s.doc_mut()?.materials.push(m);
    Ok(json!({ "name": name }))
}

fn material_name(s: &Session, p: &Value, cmd: &str) -> Result<String> {
    let n = text(p, "name")?.ok_or_else(|| bad(cmd, "`name` is required"))?;
    s.doc()?.material(&n).map(|m| m.name.clone()).ok_or_else(|| bad(cmd, format!("no material named \"{n}\"")))
}

/// Every reference to material `from` (layers, objects in every space and block) renamed to `to`,
/// or with `None` removed. Returns (layers, objects) changed.
fn rename_refs(d: &mut cadaddy_doc::Drawing, from: &str, to: Option<&str>) -> (usize, usize) {
    let mut layers = 0usize;
    for l in &mut d.layers {
        if l.material.as_deref().is_some_and(|m| m.eq_ignore_ascii_case(from)) {
            l.material = to.map(str::to_string);
            layers += 1;
        }
    }
    let mut objects = 0usize;
    let mut fix = |store: &mut cadaddy_doc::EntityStore| {
        let hs: Vec<Handle> =
            store.iter().filter(|e| e.common.material.as_deref().is_some_and(|m| m.eq_ignore_ascii_case(from))).map(|e| e.handle).collect();
        for h in hs {
            if store.modify(h, |e| e.common.material = to.map(str::to_string)) {
                objects += 1;
            }
        }
    };
    fix(&mut d.model);
    for l in &mut d.layouts {
        fix(&mut l.entities);
    }
    for b in d.blocks.values_mut() {
        if b.entities.iter().any(|e| e.common.material.as_deref().is_some_and(|m| m.eq_ignore_ascii_case(from))) {
            fix(&mut std::sync::Arc::make_mut(b).entities);
        }
    }
    if d.header.str("CMATERIAL", "").eq_ignore_ascii_case(from) {
        d.header.set_str("CMATERIAL", to.unwrap_or(material::BY_LAYER));
    }
    (layers, objects)
}

fn run_edit(s: &mut Session, p: &Value) -> Result<Value> {
    let name = material_name(s, p, "material.edit")?;
    let rename = text(p, "rename")?.map(|r| r.trim().to_string()).filter(|r| !r.eq_ignore_ascii_case(&name));
    if let Some(r) = &rename {
        check_name(s, r, Some(&name))?;
    }
    let mut m = s.doc()?.material(&name).cloned().ok_or_else(|| bad("material.edit", "no such material"))?;
    apply(&mut m, p)?;
    if let Some(r) = &rename {
        m.name.clone_from(r);
    }
    let m = m.sane();
    let new_name = m.name.clone();
    let d = s.doc_mut()?;
    if let Some(slot) = d.materials.iter_mut().find(|x| x.name.eq_ignore_ascii_case(&name)) {
        *slot = m;
    }
    if rename.is_some() {
        rename_refs(d, &name, Some(&new_name));
    }
    Ok(json!({ "name": new_name }))
}

fn run_delete(s: &mut Session, p: &Value) -> Result<Value> {
    let name = material_name(s, p, "material.delete")?;
    let d = s.doc_mut()?;
    d.materials.retain(|m| !m.name.eq_ignore_ascii_case(&name));
    let (layers, objects) = rename_refs(d, &name, None);
    Ok(json!({ "name": name, "layers": layers, "objects": objects }))
}

/// A material name for a layer: `None` for Global.
fn layer_target(s: &Session, v: &Value) -> Result<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(t) if t.trim().eq_ignore_ascii_case(material::GLOBAL) || t.trim().is_empty() => Ok(None),
        Value::String(t) => {
            s.doc()?.material(t).map(|m| Some(m.name.clone())).ok_or_else(|| bad("materialattach", format!("no material named \"{t}\"")))
        }
        v => Err(bad("materialattach", format!("`material` must be a name or null, got {v}"))),
    }
}

fn run_attach(s: &mut Session, p: &Value) -> Result<Value> {
    let pairs: Vec<(String, Value)> = match p.get("attach") {
        Some(Value::Array(a)) => a
            .iter()
            .take(10_000)
            .map(|x| {
                Ok((
                    x.get("layer").and_then(Value::as_str).ok_or_else(|| bad("materialattach", "each attachment needs a `layer`"))?.to_string(),
                    x.get("material").cloned().unwrap_or(Value::Null),
                ))
            })
            .collect::<Result<_>>()?,
        Some(_) => return Err(bad("materialattach", "`attach` must be a list of {layer, material}")),
        None => {
            vec![(text(p, "layer")?.ok_or_else(|| bad("materialattach", "`layer` is required"))?, p.get("material").cloned().unwrap_or(Value::Null))]
        }
    };
    let mut resolved = Vec::new();
    for (layer, m) in pairs {
        let target = layer_target(s, &m)?;
        let name = s.doc()?.layer(&layer).map(|l| l.name.clone()).ok_or_else(|| bad("materialattach", format!("no layer named \"{layer}\"")))?;
        resolved.push((name, target));
    }
    let d = s.doc_mut()?;
    let mut changed = 0usize;
    for (layer, target) in resolved {
        if let Some(l) = d.layers.iter_mut().find(|l| l.name == layer)
            && l.material != target
        {
            l.material = target;
            changed += 1;
        }
    }
    Ok(json!({ "changed": changed }))
}

/// A material name for objects: `None` for ByLayer.
fn object_target(s: &Session, name: &str) -> Result<Option<String>> {
    let n = name.trim();
    if n.is_empty() || n.eq_ignore_ascii_case(material::BY_LAYER) {
        return Ok(None);
    }
    if n.eq_ignore_ascii_case(material::BY_BLOCK) {
        return Ok(Some(material::BY_BLOCK.into()));
    }
    if n.eq_ignore_ascii_case(material::GLOBAL) {
        return Ok(Some(material::GLOBAL.into()));
    }
    s.doc()?.material(n).map(|m| Some(m.name.clone())).ok_or_else(|| bad("materialassign", format!("no material named \"{n}\"")))
}

fn assign(s: &mut Session, hs: &[Handle], target: Option<String>) -> Result<usize> {
    let d = s.doc_mut()?;
    let mut n = 0usize;
    for h in hs {
        if d.entity(*h).is_some_and(|e| e.common.material != target) && d.modify_entity(*h, |e| e.common.material.clone_from(&target)).is_ok() {
            n += 1;
        }
    }
    Ok(n)
}

fn run_assign(s: &mut Session, p: &Value) -> Result<Value> {
    let hs = targets(s, p)?;
    let name = text(p, "material")?.ok_or_else(|| bad("materialassign", "`material` is required"))?;
    let target = object_target(s, &name)?;
    if hs.is_empty() {
        return Err(bad("materialassign", "no objects: pass `handles` or select objects first"));
    }
    let n = assign(s, &hs, target)?;
    Ok(json!({ "changed": n }))
}

fn set_maps(s: &mut Session, hs: &[Handle], m: Option<Mapping>) -> Result<usize> {
    let d = s.doc_mut()?;
    let mut n = 0usize;
    for h in hs {
        let had = d.entity(*h).map(|e| material::object_mapping(&e.common.xdata));
        let Some(had) = had else { continue };
        if had == m {
            continue;
        }
        if d.modify_entity(*h, |e| material::set_object_mapping(&mut e.common.xdata, m.as_ref())).is_ok() {
            n += 1;
        }
    }
    Ok(n)
}

/// The mapping an object starts from: its own, else its material's, else the default.
fn base_mapping(s: &Session, h: Handle) -> Mapping {
    let Ok(d) = s.doc() else { return Mapping::default() };
    let Some(e) = d.entity(h) else { return Mapping::default() };
    material::object_mapping(&e.common.xdata).or_else(|| d.material_of(e, None).map(|m| m.mapping)).unwrap_or_default()
}

fn run_map(s: &mut Session, p: &Value) -> Result<Value> {
    let hs = targets(s, p)?;
    if hs.is_empty() {
        return Err(bad("materialmap", "no objects: pass `handles` or select objects first"));
    }
    if p.get("reset").and_then(Value::as_bool) == Some(true) {
        return Ok(json!({ "changed": set_maps(s, &hs, None)? }));
    }
    if text(p, "projection")?.is_none() {
        return Err(bad("materialmap", "`projection` (planar, box, cylindrical or spherical) or `reset: true` is required"));
    }
    // Each object from its current mapping (sizes kept unless given).
    let mut n = 0usize;
    for h in hs {
        let m = mapping(p, base_mapping(s, h))?;
        n += set_maps(s, &[h], Some(m))?;
    }
    Ok(json!({ "changed": n }))
}

/// MATERIALASSIGN at the command line: the material (CMATERIAL by default), then the objects.
#[derive(Default)]
struct AssignM {
    material: Option<Option<String>>,
    sel: SelectPhase,
}

impl Interactive for AssignM {
    fn name(&self) -> &'static str {
        "MATERIALASSIGN"
    }
    fn prompt(&self, s: &Session) -> Prompt {
        match self.material {
            None => {
                let current = s.doc().map(|d| d.header.str("CMATERIAL", material::BY_LAYER)).unwrap_or_else(|_| material::BY_LAYER.into());
                Prompt::new(format!("Enter material name <{current}>"), Accept::TEXT)
            }
            Some(_) => self.sel.prompt(),
        }
    }
    fn input(&mut self, s: &mut Session, i: Input) -> Result<Step> {
        if matches!(i, Input::Cancel) {
            return Ok(Step::Cancel);
        }
        match &self.material {
            None => {
                let typed = match &i {
                    Input::Text(t) | Input::Keyword(t) => t.trim().to_string(),
                    _ => s.doc()?.header.str("CMATERIAL", material::BY_LAYER),
                };
                match object_target(s, if typed.is_empty() { material::BY_LAYER } else { &typed }) {
                    Ok(t) => {
                        self.material = Some(t);
                        self.sel = SelectPhase::begin(s);
                        if self.sel.done {
                            let hs = self.sel.picked.clone();
                            return self.finish(s, hs);
                        }
                        Ok(Step::Continue)
                    }
                    Err(e) => {
                        s.echo(e.to_string());
                        Ok(Step::Continue)
                    }
                }
            }
            Some(_) => match self.sel.feed(s, &i)? {
                SelOutcome::More => Ok(Step::Continue),
                SelOutcome::Empty => Ok(Step::Done),
                SelOutcome::Done(hs) => self.finish(s, hs),
            },
        }
    }
}

impl AssignM {
    fn finish(&mut self, s: &mut Session, hs: Vec<Handle>) -> Result<Step> {
        let target = self.material.clone().flatten();
        let n = assign(s, &hs, target)?;
        s.set_selection(Vec::new());
        s.echo(format!("Material assigned to {n} object{}.", if n == 1 { "" } else { "s" }));
        Ok(Step::Done)
    }
}

/// MATERIALMAP at the command line: the projection (or Reset), then the objects.
#[derive(Default)]
struct MapM {
    choice: Option<Option<Projection>>,
    sel: SelectPhase,
}

impl Interactive for MapM {
    fn name(&self) -> &'static str {
        "MATERIALMAP"
    }
    fn prompt(&self, _s: &Session) -> Prompt {
        match self.choice {
            None => Prompt::new("Select an option", Accept::TEXT).kw(&["Box", "Planar", "Spherical", "Cylindrical", "Reset mapping"]).default("Box"),
            Some(_) => self.sel.prompt(),
        }
    }
    fn input(&mut self, s: &mut Session, i: Input) -> Result<Step> {
        if matches!(i, Input::Cancel) {
            return Ok(Step::Cancel);
        }
        match self.choice {
            None => {
                let t = match &i {
                    Input::Text(t) | Input::Keyword(t) => t.trim().to_ascii_lowercase(),
                    _ => "box".into(),
                };
                let choice = if t.starts_with('r') { Some(None) } else { Projection::parse(if t.is_empty() { "box" } else { &t }).map(Some) };
                let Some(c) = choice else {
                    s.echo("Invalid option keyword.");
                    return Ok(Step::Continue);
                };
                self.choice = Some(c);
                self.sel = SelectPhase::begin(s);
                if self.sel.done {
                    let hs = self.sel.picked.clone();
                    return self.finish(s, hs);
                }
                Ok(Step::Continue)
            }
            Some(_) => match self.sel.feed(s, &i)? {
                SelOutcome::More => Ok(Step::Continue),
                SelOutcome::Empty => Ok(Step::Done),
                SelOutcome::Done(hs) => self.finish(s, hs),
            },
        }
    }
}

impl MapM {
    fn finish(&mut self, s: &mut Session, hs: Vec<Handle>) -> Result<Step> {
        let r = match self.choice.flatten() {
            None => run_map(s, &json!({ "handles": hs.iter().map(|h| h.hex()).collect::<Vec<_>>(), "reset": true })),
            Some(p) => run_map(s, &json!({ "handles": hs.iter().map(|h| h.hex()).collect::<Vec<_>>(), "projection": p.as_str() })),
        };
        match r {
            Ok(v) => s.echo(format!("Mapping changed on {} object(s).", v["changed"])),
            Err(e) => s.echo(e.to_string()),
        }
        s.set_selection(Vec::new());
        Ok(Step::Done)
    }
}

/// MATERIALATTACH at the command line (where there is no Materials Browser): the layer, then the
/// material.
#[derive(Default)]
struct AttachM {
    layer: Option<String>,
}

impl Interactive for AttachM {
    fn name(&self) -> &'static str {
        "MATERIALATTACH"
    }
    fn prompt(&self, _s: &Session) -> Prompt {
        match self.layer {
            None => Prompt::new("Enter layer name", Accept::TEXT),
            Some(_) => Prompt::new(format!("Enter material name <{}>", material::GLOBAL), Accept::TEXT),
        }
    }
    fn input(&mut self, s: &mut Session, i: Input) -> Result<Step> {
        let typed = match &i {
            Input::Cancel => return Ok(Step::Cancel),
            Input::Text(t) | Input::Keyword(t) => t.trim().to_string(),
            _ => String::new(),
        };
        match self.layer.take() {
            None => {
                if typed.is_empty() {
                    return Ok(Step::Cancel);
                }
                self.layer = Some(typed);
                Ok(Step::Continue)
            }
            Some(layer) => {
                let material = if typed.is_empty() { Value::Null } else { Value::String(typed) };
                match run_attach(s, &json!({ "layer": layer, "material": material })) {
                    Ok(_) => s.echo(format!("Material attached to layer {layer}.")),
                    Err(e) => s.echo(e.to_string()),
                }
                Ok(Step::Done)
            }
        }
    }
}
